import pandas as pd
import numpy as np
import math
import path
# 1. Load the CSV file generated by your AWS script
# Replace this string with the exact name of your downloaded file
csv_path = "C:\\Users\\azuce\\Clouds\\live_cloud_data_with_cod_20261029_132020.csv" 
df = pd.read_csv(csv_path)

# 2. Filter out empty pixels (NaNs) where there were no clouds
valid_radii_um = df['Droplet_Radius_um'].dropna()

# 3. Calculate the average radius (r_avg) across the dataset
r_avg_um = valid_radii_um.mean()

# Convert the average radius to meters for standard SI physics calculations
r_avg_m = r_avg_um * 1e-6

# 4. Execute your equation: V_avg = (4/3) * pi * (r_avg)^3
v_avg_um3 = (4/3) * math.pi * (r_avg_um ** 3)
v_avg_m3 = (4/3) * math.pi * (r_avg_m ** 3)

print("="*50)
print("DROPLET VOLUME CALCULATION (SPHERICAL ASSUMPTION)")
print("="*50)
print(f"Mean Radius (r_avg) : {r_avg_um:.2f} μm")
print(f"Mean Radius (SI)    : {r_avg_m:.3e} m")
print(f"Mean Volume (V_avg) : {v_avg_um3:.2f} μm³")
print(f"Mean Volume (SI)    : {v_avg_m3:.3e} m³")
print("="*50)

# OPTIONAL: Calculate the volume for EVERY individual pixel and save it as a new column
df['Droplet_Volume_m3'] = (4/3) * np.pi * ((df['Droplet_Radius_um'] * 1e-6) ** 3)
df.to_csv("cloud_data_with_volume.csv", index=False)
print("\nSuccess! Individual droplet volumes added to 'cloud_data_with_volume.csv'")